/* isry.itgcm.casemng.uneart.mapper.RgnSoctyHnfTrnngMapper.selectRgnSoctyHnfTrnngInqList(지역사회 인력양성 목록)*/
SELECT T.* , (SUM_STDENT_NOPE + SUM_OSCHL_NOPE + SUM_IOCPTNL_NOPE + SUM_GNRL_NOPE) AS SUM_TOTAL FROM ( SELECT #{TOT_CNT} AS TOT_CNT , ROWNUM AS SEQ , T11.* , ( NVL(T11.ELESCH_STDENT_MALE_NOPE, 0) + NVL(T11.ELESCH_STDENT_FEMALE_NOPE, 0) + NVL(T11.MSKUL_STDENT_MALE_NOPE, 0) + NVL(T11.MSKUL_STDENT_FEMALE_NOPE, 0) + NVL(T11.HGSCHL_STDENT_MALE_NOPE, 0) + NVL(T11.HGSCHL_STDENT_FEMALE_NOPE, 0) + NVL(T11.UNIVA_STDENT_MALE_NOPE, 0) + NVL(T11.UNIVA_STDENT_FEMALE_NOPE, 0) ) AS SUM_STDENT_NOPE /* 재학생합계*/ , ( NVL(T11.ELESCH_OSCHL_MALE_NOPE, 0) + NVL(T11.ELESCH_OSCHL_FEMALE_NOPE, 0) + NVL(T11.MSKUL_OSCHL_MALE_NOPE, 0) + NVL(T11.MSKUL_OSCHL_FEMALE_NOPE, 0) + NVL(T11.HGSCHL_OSCHL_MALE_NOPE, 0) + NVL(T11.HGSCHL_OSCHL_FEMALE_NOPE, 0) + NVL(T11.UNIVA_OSCHL_MALE_NOPE, 0) + NVL(T11.UNIVA_OSCHL_FEMALE_NOPE, 0) ) AS SUM_OSCHL_NOPE /* 학교밖합계*/ , ( NVL(T11.AGRDHS_IOCPTN_MALE_NOPE, 0) + NVL(T11.AGRDHS_EMPYMN_MALE_NOPE, 0) + NVL(T11.AGRDHS_IOCPTN_FEMALE_NOPE, 0) + NVL(T11.AGRDHS_EMPYMN_FEMALE_NOPE, 0) ) AS SUM_IOCPTNL_NOPE /* 졸업생합계*/ , ( NVL(T11.ENFSN_MALE_NOPE, 0) + NVL(T11.ENFSN_FEMALE_NOPE, 0) + NVL(T11.TEACHR_MALE_NOPE, 0) + NVL(T11.TEACHR_FEMALE_NOPE, 0) + NVL(T11.PEPL_MALE_NOPE, 0) + NVL(T11.PEPL_FEMALE_NOPE, 0)) AS SUM_GNRL_NOPE /* 일반합계*/ FROM( SELECT T1.RGN_SOCTY_HNF_TRNNG_MNG_NO AS RGN_SOCTY_HNF_TRNNG_MNG_NO /* 지역사회인력양성관리번호*/ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드*/ , T1.EDU_BGNG_YMD AS EDU_BGNG_YMD /* 교육시작일자*/ , T1.EDU_END_YMD AS EDU_END_YMD /* 교육종료일자*/ , T1.PIC_NO AS PIC_NO /* 담당자번호*/ , T1.PIC_INST_NO AS PIC_INST_NO /* 담당자기관번호*/ , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD /* 서비스제공방법구분코드*/ , T1.EDU_TTL_NM AS EDU_TTL_NM /* 교육제목명*/ , T1.EDU_BGNG_HR AS EDU_BGNG_HR /* 교육시작시간*/ , T1.EDU_END_HR AS EDU_END_HR /* 교육종료시간*/ , T1.EDU_CN AS EDU_CN /* 교육내용*/ , T1.PLACE_NM AS PLACE_NM /* 장소명*/ , T1.ELESCH_STDENT_MALE_NOPE AS ELESCH_STDENT_MALE_NOPE /* 초등학교재학생남성인원수*/ , T1.ELESCH_STDENT_FEMALE_NOPE AS ELESCH_STDENT_FEMALE_NOPE /* 초등학교재학생여성인원수*/ , T1.MSKUL_STDENT_MALE_NOPE AS MSKUL_STDENT_MALE_NOPE /* 중학교재학생남성인원수*/ , T1.MSKUL_STDENT_FEMALE_NOPE AS MSKUL_STDENT_FEMALE_NOPE /* 중학교재학생여성인원수*/ , T1.HGSCHL_STDENT_MALE_NOPE AS HGSCHL_STDENT_MALE_NOPE /* 고등학교재학생남성인원수*/ , T1.HGSCHL_STDENT_FEMALE_NOPE AS HGSCHL_STDENT_FEMALE_NOPE /* 고등학교재학생여성인원수*/ , T1.UNIVA_STDENT_MALE_NOPE AS UNIVA_STDENT_MALE_NOPE /* 대학재학생남성인원수*/ , T1.UNIVA_STDENT_FEMALE_NOPE AS UNIVA_STDENT_FEMALE_NOPE /* 대학재학생여성인원수*/ , T1.ELESCH_OSCHL_MALE_NOPE AS ELESCH_OSCHL_MALE_NOPE /* 초등학교학교밖남성인원수*/ , T1.ELESCH_OSCHL_FEMALE_NOPE AS ELESCH_OSCHL_FEMALE_NOPE /* 초등학교학교밖여성인원수*/ , T1.MSKUL_OSCHL_MALE_NOPE AS MSKUL_OSCHL_MALE_NOPE /* 중학교학교밖남성인원수*/ , T1.MSKUL_OSCHL_FEMALE_NOPE AS MSKUL_OSCHL_FEMALE_NOPE /* 중학교학교밖여성인원수*/ , T1.HGSCHL_OSCHL_MALE_NOPE AS HGSCHL_OSCHL_MALE_NOPE /* 고등학교학교밖남성인원수*/ , T1.HGSCHL_OSCHL_FEMALE_NOPE AS HGSCHL_OSCHL_FEMALE_NOPE /* 고등학교학교밖여성인원수*/ , T1.UNIVA_OSCHL_MALE_NOPE AS UNIVA_OSCHL_MALE_NOPE /* 대학학교밖남성인원수*/ , T1.UNIVA_OSCHL_FEMALE_NOPE AS UNIVA_OSCHL_FEMALE_NOPE /* 대학학교밖여성인원수*/ , T1.AGRDHS_IOCPTN_MALE_NOPE AS AGRDHS_IOCPTN_MALE_NOPE /* 고졸후무직남성인원수*/ , T1.AGRDHS_EMPYMN_MALE_NOPE AS AGRDHS_EMPYMN_MALE_NOPE /* 고졸후취업남성인원수*/ , T1.AGRDHS_IOCPTN_FEMALE_NOPE AS AGRDHS_IOCPTN_FEMALE_NOPE /* 고졸후무직여성인원수*/ , T1.AGRDHS_EMPYMN_FEMALE_NOPE AS AGRDHS_EMPYMN_FEMALE_NOPE /* 고졸후취업여성인원수*/ , T1.ENFSN_MALE_NOPE AS ENFSN_MALE_NOPE /* 종사자남성인원수*/ , T1.ENFSN_FEMALE_NOPE AS ENFSN_FEMALE_NOPE /* 종사자여성인원수*/ , T1.TEACHR_MALE_NOPE AS TEACHR_MALE_NOPE /* 교사남성인원수*/ , T1.TEACHR_FEMALE_NOPE AS TEACHR_FEMALE_NOPE /* 교사여성인원수*/ , T1.PEPL_MALE_NOPE AS PEPL_MALE_NOPE /* 일반인남성인원수*/ , T1.PEPL_FEMALE_NOPE AS PEPL_FEMALE_NOPE /* 일반인여성인원수*/ , T1.EDU_RESULT_CN AS EDU_RESULT_CN /* 교육결과내용*/ , T1.ATFINO AS ATFINO /* 첨부파일번호*/ , T1.FRST_RGTR_ID AS FRST_RGTR_ID /* 최초등록자아이디*/ , T1.FRST_REG_DT AS FRST_REG_DT /* 최초등록일시*/ , T1.LAST_MDFR_ID AS LAST_MDFR_ID /* 최종수정자아이디*/ , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT /* 최종수정일시*/ , C##RG.DEC_B64(T2.FLNM_ENCPT) AS PIC_NM /* 담당자명암호화*/ , T3.INST_NM AS PIC_INST_NM /* 담당자기관명*/ FROM SED200 T1 /* 지역사회인력양성*/ , SCA100 T2 /* 종사자*/ , SAA000 T3 /* 통합기관*/ WHERE 1 = 1 AND T1.PIC_NO = T2.ENFSN_NO AND T1.PIC_INST_NO = T3.INST_NO(+) AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 단위업무구분코드*/ AND T1.FRST_REG_DT BETWEEN TO_DATE((#{REG_BGNG_YMD} || '000000'), 'YYYYMMDDHH24MISS') /* 등록시작일자*/ AND TO_DATE((#{REG_END_YMD} || '235959'), 'YYYYMMDDHH24MISS') /* 등록종료일자*/
ORDER BY RGN_SOCTY_HNF_TRNNG_MNG_NO DESC, FRST_REG_DT DESC ) T11 ) T WHERE 1 = 1
AND T.SEQ >= #{START_IDX} AND T.SEQ <= #{LAST_IDX}

/* 지역사회 인력양성 서비스사업 중복체크(SED210)*/
SELECT COUNT(*) AS EXCN_BIZ_CNT
  FROM SED210 
 WHERE 1 = 1
   AND RGN_SOCTY_HNF_TRNNG_MNG_NO = #{RGN_SOCTY_HNF_TRNNG_MNG_NO}
   AND SRVC_EXCN_BIZ_NO           = #{SRVC_EXCN_BIZ_NO}

/* 지역사회 인력양성 서비스사업 중복체크(SED220)*/
SELECT COUNT(*) AS EXCN_BIZ_CNT
  FROM SED220 
 WHERE 1 = 1
   AND RGN_SOCTY_HNF_TRNNG_MNG_NO    = #{RGN_SOCTY_HNF_TRNNG_MNG_NO}
   AND EXCN_SRVC_BIZ_CL_NO           = #{EXCN_SRVC_BIZ_CL_NO}
   AND EXCN_SRVC_DETAIA_BIZ_NO       = #{EXCN_SRVC_DETAIA_BIZ_NO}

